    super().__init__()
    self.config = config
    self.act = get_act_dummy(config)
    self.register_buffer('sigmas', torch.tensor([1.0]))
    self.groups = config.model.group
    self.en_nf = config.model.en_nf
    self.stage_num = config.model.stage_num
