    self.attn_resolutions = config.model.attn_resolutions
    dropout = config.model.dropout
    resamp_with_conv = config.model.resamp_with_conv
    self.num_resolutions = len(ch_mult)
    self.all_resolutions = [config.data.image_size // (2 ** i) for i in range(self.num_resolutions)]

    self.conditional = config.model.conditional
    fir = config.model.fir
    fir_kernel = config.model.fir_kernel
    self.skip_rescale = config.model.skip_rescale
    self.resblock_type = config.model.resblock_type.lower()
    self.progressive = config.model.progressive.lower()
    self.progressive_input = config.model.progressive_input.lower()
    self.embedding_type = config.model.embedding_type.lower()
    init_scale = config.model.init_scale

    embed_dim = self.en_nf
    self.time_embed = nn.Sequential(
        LinearDummy(embed_dim, self.en_nf * 4),
        nn.SiLU(),
        LinearDummy(self.en_nf * 4, self.en_nf * 4),
    )
    if self.conditional:
        self.cond_map1 = LinearDummy(embed_dim, self.en_nf * 4)
        self.cond_map2 = LinearDummy(self.en_nf * 4, self.en_nf * 4)

    self.conv_in = Conv2dDummy(config.data.num_channels, self.en_nf)
    self.en_blocks = nn.ModuleList()
    curr_ch = self.en_nf
    for level, mult in enumerate(ch_mult):
        for _ in range(self.num_res_blocks):
            self.en_blocks.append(ResnetBlockDummy(curr_ch, mult * self.en_nf))
            curr_ch = mult * self.en_nf
            if self.all_resolutions[level] in self.attn_resolutions:
                self.en_blocks.append(AttnBlockDummy(curr_ch))
        if level != self.num_resolutions - 1:
            self.en_blocks.append(DownsampleDummy(curr_ch, resamp_with_conv))

    self.mid_blocks = nn.ModuleList([
        ResnetBlockDummy(curr_ch, curr_ch),
        AttnBlockDummy(curr_ch),
        ResnetBlockDummy(curr_ch, curr_ch)
    ])

    self.de_modules = nn.ModuleList()
    self.outs = nn.ModuleList()
    for i_stage in range(self.stage_num):
      de_level_blocks = nn.ModuleList()
      current_de_ch = curr_ch

      for level in reversed(range(self.num_resolutions)):
          num_blocks_at_level = self.num_res_blocks + 1 
          for _ in range(num_blocks_at_level):
              de_level_blocks.append(ResnetBlockDummy(current_de_ch *2, self.de_nfs[i_stage] * ch_mult[level]))
              current_de_ch = self.de_nfs[i_stage] * ch_mult[level]
              if self.all_resolutions[level] in self.attn_resolutions:
                  de_level_blocks.append(AttnBlockDummy(current_de_ch))
          if level != 0:
              de_level_blocks.append(UpsampleDummy(current_de_ch, resamp_with_conv))

      self.de_modules.append(de_level_blocks)
      self.outs.append(Conv2dDummy(current_de_ch, config.data.num_channels))

  def forward(self, x, time_cond, context=None, y=None):
    current_stage = 0
    time_val = time_cond[0] / 1000.0

    for i_stage, intervals in enumerate(self.stage_interval):
        for interval in intervals:
            if time_val > interval[0] and time_val <= interval[1]:
                current_stage = i_stage
                break
        if current_stage == i_stage:
            break

    temb_raw = PositionalEmbeddingDummy(self.en_nf)(time_cond);
    temb = self.time_embed(temb_raw)
    if self.conditional:
        temb = self.cond_map1(temb)
        temb = self.act(temb)
        temb = self.cond_map2(temb)

    if not self.config.data.centered:
        x = 2 * x - 1.

    hs = [self.conv_in(x)]
    for block in self.en_blocks:
        if isinstance(block, ResnetBlockDummy):
            h = block(hs[-1], temb)
        elif isinstance(block, AttnBlockDummy):
            h = block(hs[-1])
        elif isinstance(block, DownsampleDummy):
            h = block(hs[-1])
        hs.append(h)

    h = hs[-1]
    for block in self.mid_blocks:
        if isinstance(block, ResnetBlockDummy):
            h = block(h, temb)
        elif isinstance(block, AttnBlockDummy):
            h = block(h)

    de_modules = self.de_modules[current_stage]
    hs_copy_for_decoder = hs.copy()

    for module_idx, block in enumerate(de_modules):
        if isinstance(block, ResnetBlockDummy):
            if hs_copy_for_decoder:
                skip = hs_copy_for_decoder.pop()
                h = block(torch.cat([h, skip], dim=1), temb)
            else:
                h = block(h, temb)
        elif isinstance(block, AttnBlockDummy):
            h = block(h)
        elif isinstance(block, UpsampleDummy):
            h = block(h)

    out = self.outs[current_stage](h)

    if self.config.model.scale_by_sigma:
        out = out / self.sigmas[time_cond.long()].reshape((x.shape[0], *([1] * len(x.shape[1:]))))

    return out

